function createTracker(target,tolerance=10){let last=null,total=0,lap=0,lapStart=0,reliable=true;return{get distance(){return total},get last(){return last},resetAnchor(){last=null;reliable=false},update(f){const laps=[];if(![f.lat,f.lon,f.elapsed,f.accuracy].every(Number.isFinite)||f.accuracy>35){last=null;reliable=false;return{laps,status:'weak'}}if(!last){last=f;if(total===0)lapStart=f.elapsed;return{laps,status:'ready'}}let dt=f.elapsed-last.elapsed;if(dt<=0)return{laps,status:'old'};if(dt>30){last=f;reliable=false;return{laps,status:'gap'}}const metres=distance(last,f);if(metres/dt>9){last=null;reliable=false;return{laps,status:'jump'}}if(metres<5)return{laps,status:'ready'};const previous=total;total+=metres;while(total>=(lap+1)*1000){const boundary=(lap+1)*1000,cross=last.elapsed+dt*(boundary-previous)/metres,pace=cross-lapStart;lap++;laps.push({km:lap,pace,reliable,status:reliable?classify(pace,target,tolerance):'gap'});lapStart=cross;reliable=true}last=f;return{laps,status:'ready'}}}}
